fn defensive_crisis(version, rnd, player, data, target, debug) -> (bool, bool)

// [19] 틱 기준
tps = data.context.setting.tick_per_second            // GameSetting+0x12f8

// [21~29] 근처 적 챔피언 수집 (bump 할당)
enemy = 1 - player.info.team                          // PlayerState+0x930, 범위밖이면 panic_bounds_check(len=2)
near_enemies: Vec<&Entity, &Bump> =
  data.cache.player_champion[enemy]                   // AbstractGameWithCache+0x1e0, [Option<&Entity>;5]
    .iter().flatten()                                 // iter_champions 의 FilterMap 클로저
    .filter(|e| <필터 클로저: 아래 별항>)
    .collect_in(data.context.pool)

// [30] 근처 적이 없으면 위기 아님
if near_enemies.len() == 0 { return (false, false) }

// [32~35] 죽음 임박 판정
die_imminent =
  match data.cache.player_by_champion_id(target.id) {  // Entity+0x5c0
    null => false,                                     // 소유 플레이어를 못 찾으면 판정 포기
    tp   => {
      die = fight_check::check_kill_die_tick(
              version, rnd, data, tp, target,
              near_enemies.clone(),      // 적 목록
              Vec::new_in(pool),         // 빈 Vec (아군 목록 자리 — 항상 비어 있다)
              debug)
      die < tps * 2                       // [35] 2초 안에 죽는다
    }
  }
// ※ near_enemies 가 clone 뒤 len==0 이면 (die_imminent, false) 로 조기 반환

// [41~50] 적이 지금 쓸 수 있는 CC 스킬을 갖고 있는가
cc_ready = near_enemies.iter().any(|e| {
  slots = [                                           // [42~46]
    (&e.skill_effect,  if e.ty==Champion { e.ty.skill_cooldown  } else { 0 }),   // [43]
    (if e.level>2 { &e.skill2_effect } else { &NONE },
                       if e.ty==Champion { e.ty.skill2_cooldown } else { 0 }),   // [44]
    (if e.level>4 { &e.ult_effect    } else { &NONE },
                       if e.ty==Champion { e.ty.ult_cooldown    } else { 0 }),   // [45]
  ]
  slots.iter().any(|(ef, cd)| {                       // [47] 순서 = skill → skill2 → ult, 단락평가
    if *cd > tps { return false }                     // [48] 쿨이 1초(=tps)보다 많이 남았으면 무시
    if ef.discriminant == -1 { return false }         //      None 이면 무시
    fight_check::effect_cc_time(version, ef).is_some() //     CC 시간이 있으면 true
  })
})

return (die_imminent, cc_ready)                        // [53]


